            body.push_str(&phrases[start..end]);
        }
        body.push_str("\" tail=\"reusable phrase reusable phrase /api/v1/items template=/tenant/{id}/resource/{name}\" \n");
    }

    let mut out = dict;
    out.extend_from_slice(body.as_bytes());
    out
